381			// ISSUANCE_STORE_CLOSED, ISSUANCE_SUBSTRATE_FAILURE, and
382			// ISSUANCE_OUTCOME_UNKNOWN without delegating to terminal suppression.
383			this.#assertAvailable();
384			const captured = this.#capturePublicationInput(input);
385			let transaction: IDBTransaction;
386			try {
387				transaction = this.#startTransaction("readwrite");
388			} catch (error) {
389				this.#assertAvailable();
390				throw error;
391			}
392			const terminal = transactionResult(transaction);
393			let reason: Error | undefined;
394			try {
395				const key = [captured.scope.objectId, captured.scope.author, captured.authorSequence];
396				const rawLineage = await requestResult(
397					transaction.objectStore("lineages").get([captured.scope.objectId, captured.scope.author])
398				);
399				const rawIssued = await requestResult(transaction.objectStore("issuedRecords").get(key));
400				const rawOutbox = await requestResult(transaction.objectStore("issuanceOutbox").get(key));
401				let observation: TerminalReadback;
402				try {
403					observation = this.#terminalFromRaw(captured.scope, rawLineage, rawIssued, rawOutbox);
404				} catch (error) {
405					reason = error instanceof Error ? error : this.#latchCorruption("publication closure is unreadable");
406					transaction.abort();
407					throw reason;
408				}
409				const status = this.#publicationStatus(observation, captured);
410				if (status === "never-issued") reason = invalid("publication address has never been issued");
411				else if (status === "pruned") {
412					reason = createDurableIssuanceRecordPrunedError(captured.scope, captured.authorSequence);
413				} else if (status === "foreign-digest") {
414					reason = invalid("publication digest does not identify the issued closure");
415				} else if (status === "corrupt") {
416					reason = this.#latchCorruption("publication closure is incomplete or malformed");
417				} else if (status === "pending") {
418					const row = observation.outboxRecord;
419					if (row === null) throw this.#latchCorruption("publication outbox row disappeared");
420					const writtenKey = await requestResult(
421						transaction.objectStore("issuanceOutbox").put({
422							author: row.scope.author,
423							authorSequence: row.authorSequence,
424							digest: new Uint8Array(row.digest),
425							objectId: row.scope.objectId,
426							publishState: "published",
427						})
