434				if (reason !== undefined) transaction.abort();
435				await terminal;
436				if (reason !== undefined) throw reason;
437			} catch {
438				await terminal.catch(() => undefined);
439				if (reason !== undefined) throw reason;
440				if (this.#closed || this.#poison !== undefined) this.#assertAvailable();
441				return this.#classifyPublicationReadback(captured, "ambiguous");
442			}
443			this.#assertAvailable();
444			return this.#classifyPublicationReadback(captured, "success");
