587					requestResult(transaction.objectStore("issuanceOutbox").getAll()),
588					requestResult(transaction.objectStore("issuedRecords").getAll()),
589					requestResult(transaction.objectStore("lineages").getAll()),
590				]);
591				await transactionResult(transaction);
