757				}
758				const from = current.prunedThroughAuthorSequence === null ? 0 : current.prunedThroughAuthorSequence + 1;
759				if (!authenticatedSettled) {
760					const rawPlan = await requestResult(settlementPlans.get([captured.scope.objectId, captured.scope.author]));
761					plan = rawPlan === undefined ? null : copyNativeSettlementPlan(rawPlan, captured.scope);
762					if (rawPlan !== undefined && plan === undefined) {
763						throw this.#latchCorruption("stored settlement plan is malformed");
