765				}
766				if (
767					!authenticatedSettled &&
768					plan?.entries.some(
769						(entry) =>
770							entry.replacementSequence === null &&
771							entry.sourceSequence >= from &&
772							entry.sourceSequence <= captured.throughAuthorSequence
