774				) {
775					throw createDurableIssuanceFailure(
776						"ISSUANCE_RETRY_REQUIRED",
777						"settlement plan still references the selected prefix"
778					);
779				}
780				for (let pageFrom = from; pageFrom <= captured.throughAuthorSequence; pageFrom += 64) {
781					const pageThrough = Math.min(captured.throughAuthorSequence, pageFrom + 63);
782					for (let authorSequence = pageFrom; authorSequence <= pageThrough; authorSequence += 1) {
783						const key = [captured.scope.objectId, captured.scope.author, authorSequence];
