785						const rawOutbox = await requestResult(issuanceOutbox.get(key));
786						const issued = rawIssued === undefined ? undefined : copyNativeIssued(rawIssued);
787						const outbox = rawOutbox === undefined ? undefined : copyNativeOutbox(rawOutbox);
788						if (
789							issued === undefined ||
790							outbox === undefined ||
791							issued.authorSequence !== authorSequence ||
792							outbox.authorSequence !== authorSequence ||
793							!this.#bytesEqual(issued.digest, outbox.digest)
