477			let committing = false;
478			try {
479				this.#database.exec("BEGIN IMMEDIATE");
480				began = true;
481				const observation = this.#queryTerminal(captured.scope, captured.authorSequence);
482				const status = this.#publicationStatus(observation, captured);
483				if (status === "never-issued") {
484					this.#database.exec("ROLLBACK");
485					began = false;
486					throw invalid("publication address has never been issued");
487				}
488				if (status === "pruned") {
489					this.#database.exec("ROLLBACK");
490					began = false;
491					throw createDurableIssuanceRecordPrunedError(captured.scope, captured.authorSequence);
492				}
493				if (status === "foreign-digest") {
494					this.#database.exec("ROLLBACK");
495					began = false;
496					throw invalid("publication digest does not identify the issued closure");
