669					this.#database,
670					"SELECT object_id,author,author_sequence,digest,publish_state FROM issuance_outbox"
671				).all();
672				this.#database.exec("COMMIT");
673				const lineageByScope = new Map<string, NativeLineage>();
674				for (const raw of lineageRows) {
675					const row = copyLineageRow(raw);
676					if (row === undefined) throw this.#latchCorruption("stored lineage is malformed");
677					lineageByScope.set(this.#scopeKey(row), row);
678				}
679				const issuedByKey = new Map<string, NativeIssuedRow>();
680				for (const raw of issuedRows) {
681					const row = copyIssuedRow(raw);
682					if (row === undefined) throw this.#latchCorruption("stored issued record is malformed");
683					issuedByKey.set(this.#key(row, row.authorSequence), row);
684				}
685				const records: DurableIssuanceOutboxRecord[] = [];
686				for (const raw of outboxRows) {
687					const row = copyOutboxRow(raw);
688					if (row === undefined) throw this.#latchCorruption("stored outbox row is malformed");
